export const EXTRA_PETS={mole:{name:'Thạch thử',shape:'turtle',grade:0,icon:'鼠',bonus:{hp:8},gather:{ore:15},unlock:0},sprout:{name:'Mộc linh',shape:'deer',grade:0,icon:'葉',bonus:{mp:8},gather:{herb:15},unlock:0},moth:{name:'Nguyệt điệp',shape:'phoenix',grade:1,icon:'蝶',bonus:{mp:15},gather:{energy:25},unlock:1},badger:{name:'Thiết chồn',shape:'wolf',grade:1,icon:'獾',bonus:{def:3},gather:{ore:25},unlock:1},jade:{name:'Ngọc quy',shape:'turtle',grade:2,icon:'玉',bonus:{def:6},gather:{ore:40},unlock:2},lotus:{name:'Liên hạc',shape:'crane',grade:2,icon:'蓮',bonus:{hp:30},gather:{herb:40},unlock:2},ember:{name:'Viêm lang',shape:'wolf',grade:3,icon:'炎',bonus:{atk:14},gather:{ore:60},unlock:3},bloom:{name:'Hồng lộc',shape:'deer',grade:3,icon:'花',bonus:{hp:45},gather:{herb:60},unlock:3},sunbird:{name:'Dương điểu',shape:'crane',grade:3,icon:'陽',bonus:{mp:30},gather:{energy:60},unlock:3},aurora:{name:'Thiên phượng',shape:'phoenix',grade:4,icon:'天',bonus:{atk:16,mp:20},gather:{energy:85},unlock:4},sovereign:{name:'Kim quy',shape:'turtle',grade:4,icon:'金',bonus:{def:10},gather:{ore:85},unlock:4},orchid:{name:'Tiên lộc',shape:'deer',grade:4,icon:'仙',bonus:{hp:70},gather:{herb:85},unlock:4}};
export const SLOT_LEVELS=[1,3,5,8,12,16,22,28,36,45];
export function petSlotCount(s){const story=[true,s.quest>=2,s.quest>=4,s.quest>=6,s.quest>=8,s.quest>=12,s.regions?.truc?.quest>=4,s.regions?.bang?.quest>=4,s.regions?.hoa?.quest>=4,s.regions?.thien?.quest>=4];return SLOT_LEVELS.filter((v,i)=>s.level>=v||story[i]).length;}
export function deployedPets(s){return (s.petDeck||[]).map(id=>s.petRoster?.find(p=>p.id===id)).filter(Boolean).slice(0,petSlotCount(s));}
export function gatherBoost(s,kind,catalog){return deployedPets(s).reduce((sum,it)=>sum+(catalog[it.species]?.gather?.[kind]||0)*(1+(it.rank-1)*.1+it.treasure*.1),0);}
export const gatherSeconds=(boost=0)=>10/(1+Math.max(0,boost)/100);
